<script setup lang="ts">
import {computed} from 'vue';
import type {SubagentSource} from './projects-model';
import {date} from './task-directory-model';
const props=withDefaults(defineProps<{sources:SubagentSource[];query?:string;safe:(v:unknown)=>string}>(),{query:''});
const count=computed(()=>props.sources.reduce((n,s)=>n+s.subagents.length,0));
const matches=computed(()=>props.sources.flatMap(s=>s.subagents).filter(a=>!props.query||[a.name,a.description,a.path,a.definitionPath,a.provider,a.model].join(' ').toLocaleLowerCase().includes(props.query.toLocaleLowerCase())));
const statuses:Record<string,string>={candidate:'范围内定义',disabled:'已禁用',shadowed:'同名覆盖',pending_commit:'待提交变化'};
</script>
<template><section class="ar-skill-group ar-subagents"><h3>子代理<span class="ar-group-count">{{count}}</span></h3><template v-for="(source,index) in sources" :key="index"><p v-if="source.warning" class="ar-warning">{{safe(source.warning)}}</p><p v-for="(warning,index) in source.warnings??[]" :key="index" class="ar-warning">{{safe(warning)}}</p><p v-if="source.state==='dirty'" class="ar-warning">存在未提交子代理变化，当前展示已提交版本。</p></template><details v-for="agent in matches" :key="agent.provider+':'+agent.name+':'+agent.path" class="ar-skill ar-subagent" :data-skill-path="'subagent:'+agent.provider+':'+agent.name+':'+agent.path"><summary><span class="ar-skill-heading"><strong>{{safe(agent.name)}}</strong><span class="ar-status" :class="agent.status??'candidate'">{{statuses[agent.status??'candidate']??'状态待核验'}}</span></span><span class="ar-skill-time">{{safe(agent.provider+' · 更新于 '+date(agent.updatedAt))}}</span></summary><div class="ar-skill-body"><p>{{safe(agent.description||'没有子代理描述')}}</p><code class="ar-path">{{safe(agent.path)}}</code><code v-if="agent.definitionPath" class="ar-path">{{safe(agent.definitionPath)}}</code><p class="ar-meta">{{safe([agent.provider,agent.model?'模型 '+agent.model:null,agent.reasoningEffort?'思考 '+agent.reasoningEffort:null,agent.mode==='all'?'可作主代理或子代理':null,agent.hidden?'执行器菜单隐藏':null].filter(Boolean).join(' · '))}}</p><p class="ar-condition">{{safe(agent.appliesWhen)}}</p><p v-if="agent.disabledReason" class="ar-warning">{{safe(agent.disabledReason)}}</p><p v-if="agent.overriddenBy" class="ar-warning">{{safe('当前目录索引被 '+agent.overriddenBy+' 覆盖')}}</p><p class="ar-meta">{{safe('提交 '+(agent.updatedCommit?.slice(0,12)||'未记录'))}}</p></div></details><p v-if="!matches.length" class="ar-muted">{{sources.length&&sources.every(s=>s.state==='unavailable')?'此范围子代理暂不可扫描':query?'没有匹配子代理':'没有已提交的子代理'}}</p><p class="ar-muted">定义扫描仅供查看；实际注册、继承与调用以对应执行器的配置及权限为准。</p></section></template>
